SET SCHEMA "BSCL"; 
DROP VIEW "BSCL.Replica.BD.Vistas::Sebra.PARAMETRO"; 

CREATE VIEW "BSCL.Replica.BD.Vistas::Sebra.PARAMETRO" AS

	SELECT 
		"par_id" AS "PAR_ID", --[par_id] [varchar](10) NOT NULL,
		"tpa_id" AS "TPA_ID", --[tpa_id] [char](5) NOT NULL,
		"par_codigo" AS "PAR_CODIGO", --[par_codigo] [varchar](5) NOT NULL,
		"par_nombre" AS "PAR_NOMBRE", --[par_nombre] [varchar](50) NOT NULL,
		"par_agrupador" AS "PAR_AGRUPADOR", --[par_agrupador] [varchar](20) NOT NULL,
		"par_valor" AS "PAR_VALOR", --[par_valor] [varchar](20) NOT NULL,
		"par_descripcion" AS "PAR_DESCRIPCION"--[par_descripcion] [varchar](500) NOT NULL,
	FROM (
	 select COD_COB_TRUN."IdPerfilProductos" as "par_id",'TPPRO' as "tpa_id",'BCS' as "par_codigo", LEFT("DescripcionPerfilProductos",50) as "par_nombre",'' as "par_agrupador",'' as "par_valor",'' as "par_descripcion" 
	 FROM "BSCL.Plataforma.BD::COM.PerfilProductos" COB
	 LEFT JOIN (
			SELECT "IdPerfilProductosKey", CASE WHEN RANK > 1 THEN CONCAT(RPAD("IdPerfilProductos",9),RANK) ELSE "IdPerfilProductos" END AS "IdPerfilProductos" FROM (
				SELECT RANK() OVER (PARTITION BY RPAD("IdPerfilProductos",10) ORDER BY "IdPerfilProductos" ASC)  as RANK, "IdPerfilProductos" AS "IdPerfilProductosKey", RPAD("IdPerfilProductos",10) AS "IdPerfilProductos" 
				FROM "BSCL.Plataforma.BD::COM.PerfilProductos" 
			) WHERE RANK < 10
		) AS COD_COB_TRUN ON COD_COB_TRUN."IdPerfilProductosKey" = COB."IdPerfilProductos"
		where "EsPerfilPersonalizado" = 'N'  
	 union
	 select COD_COB_TRUN."IdPerfilCobros" as "par_id",'TPCOB' as "tpa_id",'BCS' as "par_codigo", LEFT("DescripcionPerfilCobros",50) as "par_nombre",'' as "par_agrupador",'' as "par_valor",'' as "par_descripcion" 
	 FROM "BSCL.Plataforma.BD::COM.PerfilCobros" COB
	 LEFT JOIN (
			SELECT "IdPerfilCobrosKey", CASE WHEN RANK > 1 THEN CONCAT(RPAD("IdPerfilCobros",9),RANK) ELSE "IdPerfilCobros" END AS "IdPerfilCobros" FROM (
				SELECT RANK() OVER (PARTITION BY RPAD("IdPerfilCobros",10) ORDER BY "IdPerfilCobros" ASC)  as RANK, "IdPerfilCobros" AS "IdPerfilCobrosKey", RPAD("IdPerfilCobros",10) AS "IdPerfilCobros" 
				FROM "BSCL.Plataforma.BD::COM.PerfilCobros" 
			) WHERE RANK < 10
		) AS COD_COB_TRUN ON COD_COB_TRUN."IdPerfilCobrosKey" = COB."IdPerfilCobros"
	 where "EsPerfilPersonalizado" = 'N' 
	 union 
	 select 'BACARMODIA' as "par_id",'BACAR' as "tpa_id",'MODIA' as "par_codigo",'Monto Operación por días' as "par_nombre",'' as "par_agrupador",'' as "par_valor",'' as "par_descripcion" from dummy union 
	 select 'BACARMOPER' as "par_id",'BACAR' as "tpa_id",'MOPER' as "par_codigo",'Monto Operación' as "par_nombre",'' as "par_agrupador",'' as "par_valor",'' as "par_descripcion" from dummy union 
	 select 'BACARMOPLA' as "par_id",'BACAR' as "tpa_id",'MOPLA' as "par_codigo",'Monto Operación por plazo' as "par_nombre",'' as "par_agrupador",'' as "par_valor",'' as "par_descripcion" from dummy union 
	 select 'BOLSACS' as "par_id",'BOLSA' as "tpa_id",'BCS' as "par_codigo",'BCS' as "par_nombre",'' as "par_agrupador",'-1' as "par_valor",'Bolsa Comercio Santiago' as "par_descripcion" from dummy union 
	 select 'BOLSACV' as "par_id",'BOLSA' as "tpa_id",'BCV' as "par_codigo",'BCV' as "par_nombre",'' as "par_agrupador",'0' as "par_valor",'Bolsa Comercio Valparaíso' as "par_descripcion" from dummy union 
